function Icon({ label, size = 20 }) {
  return <span style={{ fontSize: size, width: size, height: size }} className="inline-flex items-center justify-center">{label}</span>;
}

const YOU_LOGO_SRC = "data:image/png;base64,";

function YouLogo({ compact = false }) {
  return (
    <span className={compact ? "you-logo-wrap you-logo-wrap-compact" : "you-logo-wrap"}>
      <img src={YOU_LOGO_SRC} alt="Youth Opportunities Unlimited" className="you-logo-image" />
      <span className="you-logo-mask" aria-hidden="true" />
    </span>
  );
}

