function percent(profile) {
  return Math.round(((profile.completed?.length || 0) / TABS.length) * 100);
}

async function copyToClipboard(value) {
  const text = String(value ?? "");
  if (!text) return false;
  if (navigator?.clipboard?.writeText) {
    try {
      await navigator.clipboard.writeText(text);
      return true;
    } catch {
      // Some local preview/browser permission states block the Clipboard API.
    }
  }
  const holder = document.createElement("textarea");
  holder.value = text;
  holder.setAttribute("readonly", "");
  holder.style.position = "fixed";
  holder.style.opacity = "0";
  document.body.appendChild(holder);
  holder.select();
  document.execCommand("copy");
  document.body.removeChild(holder);
  return true;
}

function CopyButton({ value, label = "Copy" }) {
  const [copied, setCopied] = useState(false);

  async function handleCopy(e) {
    e.preventDefault();
    e.stopPropagation();
    const ok = await copyToClipboard(value);
    if (!ok) return;
    setCopied(true);
    window.setTimeout(() => setCopied(false), 1200);
  }

  return (
    <button type="button" onClick={handleCopy} className="shrink-0 border-2 border-[#0b4a56] bg-white px-3 py-2 text-xs font-black uppercase tracking-wide text-[#0b4a56]" aria-label={`${label} value`}>
      {copied ? "Copied" : label}
    </button>
  );
}

