function noteHistory(profile) {
  const departmentNotes = Object.entries(profile?.departmentNotes || {}).flatMap(([department, notes]) =>
    notes.map((item) => ({ ...item, department }))
  );
  const legacyNotes = (profile?.notes || []).map((text, index) => ({
    id: `legacy-${profile?.id || "profile"}-${index}`,
    department: "Case Note",
    author: "Existing record",
    role: "Imported note",
    date: "Existing history",
    text,
  }));
  return [...departmentNotes, ...legacyNotes].sort((a, b) => {
    const aTime = Date.parse(a.date);
    const bTime = Date.parse(b.date);
    if (Number.isNaN(aTime) || Number.isNaN(bTime)) return 0;
    return bTime - aTime;
  });
}

function displayDate(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleString([], { month: "short", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit" });
}

